cards.solution:
def cek_jumlah(teks):
    n = int(teks)
    if n < 1 or n > 99:
        raise ValueError("jumlah harus 1 sampai 99")
    return n

for _ in range(int(input())):
    t = input()
    try:
        n = cek_jumlah(t)
    except ValueError:
        print("Tolak")
    else:
        print("OK", n)

